import { ConflictError, ValidationError } from '../errors/DomainErrors';
import { DueDate } from '../value-objects/DueDate';
import { TaskStatus } from '../value-objects/TaskStatus';

export interface NewTaskProps {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate: DueDate | null;
  status: TaskStatus;
}

export class Task {
  private assignee: string | null = null;

  private constructor(
    readonly id: string,
    readonly projectId: string,
    readonly title: string,
    readonly description: string,
    readonly dueDate: DueDate | null,
    private currentStatus: TaskStatus,
  ) {}

  static create(props: NewTaskProps): Task {
    const title = props.title.trim();
    if (title.length === 0) {
      throw new ValidationError('Task title must not be empty');
    }
    return new Task(props.id, props.projectId, title, props.description, props.dueDate, props.status);
  }

  get status(): TaskStatus {
    return this.currentStatus;
  }

  get assigneeId(): string | null {
    return this.assignee;
  }

  /** Callers must ensure the user exists; see TaskAssignmentService. */
  assignTo(userId: string): void {
    this.assignee = userId;
  }

  markDone(): void {
    if (this.currentStatus.isDone()) {
      throw new ConflictError(`Task '${this.id}' is already done`);
    }
    this.currentStatus = TaskStatus.DONE;
  }
}

